 need(argc==7&&ranks==1,"packet saved sites weights mixed_input_registry NEWdest");auto start=std::chrono::steady_clock::now();const auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);const auto before=f.coefficient;auto site=sites(argv[3],argv[4]);std::sort(site.begin(),site.end(),[](const Site&a,const Site&b){return a.id<b.id;});std::string input=argv[5],dest=argv[6],line;
 std::map<uint64_t,std::string>packet_paths;std::ifstream registry(input+"/../shared_atlas_adoption_v7/typed_packet_registry.csv");need(bool(registry),"same v7 packet registry");std::getline(registry,line);while(std::getline(registry,line)){auto c=target::columns(line);packet_paths.emplace(std::stoull(c[0]),c[1]);}
