 std::map<std::string,std::vector<TypedPanel>>plans;std::map<std::string,std::vector<pr::Boundary>>boundaries;std::vector<RealGroup>work;std::ifstream groups(input+"/real_graph_groups.csv");need(bool(groups),"same prepared graph groups");std::getline(groups,line);
 while(std::getline(groups,line)){auto c=target::columns(line);if(c[4]!="regular_saved_axis1_domain")continue;RealGroup w;w.group=std::stoull(c[0]);w.slot=std::stoull(c[1]);w.source=std::stoull(c[2]);w.target=std::stoull(c[3]);auto location=panel_record.at({w.slot,std::stoull(c[5])});auto path=packet_paths.at(location.first);if(!plans.count(path))plans.emplace(path,baseline_read(path));w.first=plans.at(path).at(location.second);if(!boundaries.count(c[9]))boundaries.emplace(c[9],read29<pr::Boundary>(c[9]));w.saved=boundaries.at(c[9]).at(std::stoull(c[10]));need(w.first.slot==w.slot&&w.first.source==w.source&&w.first.target==w.target&&w.first.index==std::stoull(c[5])&&!w.first.geometry.whole,"same remaining original implicit panel");need(w.saved.slot==w.slot&&w.saved.source==w.source&&w.saved.target==w.target&&w.saved.axis==1&&w.saved.chart==uint64_t(w.first.geometry.strip.chart),"same saved full-real-free-axis implicit domain");work.push_back(std::move(w));}
